def build():
    rows=[]
    for index,(hook,family,body,ig,fb,assets) in enumerate(IDEAS,1):
        rows.append({"id":f"s5o{index:02d}","day_index":index-1,"family":family,"hook":hook,
          "format":"carousel" if len(assets)>1 else "image","assets":assets,
          "alt":f"Solacen SootheSight S5 eye massager: {hook}",
          "instagram_caption":f"{hook}\n\n{body}\n\n{ig}\nExplore S5: link in bio.\n\n#Solacen #EveningRoutine #SootheSight",
          "facebook_caption":f"{hook}\n\n{body}\n\n{fb}\n\nExplore S5: {{url}}",
          "ai_assisted":True,"review_state":"ready","generation_cost_eur":0,
          "claim_source":"product.json; live page checked 22 November 2026"})
    (ROOT/'queue.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    return rows

if __name__=='__main__':
    print(f"Saved {len(build())} distinct post concepts with captions for both platforms.")
